 ('BANG_CONG_THANG','{"madinhdanh":{"type":"text","nullable":"NO","generated":"NEVER"},"dakhoa":{"type":"boolean","nullable":"NO","generated":"NEVER"},"daguithongbao":{"type":"boolean","nullable":"NO","generated":"NEVER"},"thoigiankhoa":{"type":"date","nullable":"YES","generated":"NEVER"},"lydomokhoa":{"type":"text","nullable":"YES","generated":"NEVER"},"kycong":{"type":"text","nullable":"NO","generated":"NEVER"},"ngaytao":{"type":"date","nullable":"NO","generated":"NEVER"},"ngaycapnhat":{"type":"date","nullable":"NO","generated":"NEVER"}}'::jsonb,'["CHECK ((kycong ~ ''^\\d{4}-(0[1-9]|1[0-2])$''::text))","PRIMARY KEY (madinhdanh)","UNIQUE (kycong)"]'::jsonb,'[]'::jsonb,'Kỳ công; mã tháng là khóa ứng viên. Khóa/gửi/mở kỳ là trạng thái của cả kỳ, không lưu tổng công.'),
 ('BIEN_BAN_DU_GIO','{"madinhdanh":{"type":"text","nullable":"NO","generated":"NEVER"},"mabienban":{"type":"text","nullable":"NO","generated":"NEVER"},"mabuoi":{"type":"text","nullable":"NO","generated":"NEVER"},"manguoidanhgia":{"type":"text","nullable":"YES","generated":"NEVER"},"ngaydanhgia":{"type":"date","nullable":"NO","generated":"NEVER"},"guiluc":{"type":"date","nullable":"YES","generated":"NEVER"},"nhanxetchung":{"type":"text","nullable":"NO","generated":"NEVER"},"uudiem":{"type":"text","nullable":"NO","generated":"NEVER"},"cancaithien":{"type":"text","nullable":"NO","generated":"NEVER"},"khuyennghi":{"type":"text","nullable":"NO","generated":"NEVER"},"trangthai":{"type":"text","nullable":"NO","generated":"NEVER"},"ngaytao":{"type":"date","nullable":"NO","generated":"NEVER"},"ngaycapnhat":{"type":"date","nullable":"NO","generated":"NEVER"},"diemtc1":{"type":"numeric","nullable":"NO","generated":"NEVER"},"diemtc2":{"type":"numeric","nullable":"NO","generated":"NEVER"},"diemtc3":{"type":"numeric","nullable":"NO","generated":"NEVER"}}'::jsonb,'["CHECK (((diemtc1 >= (0)::numeric) AND (diemtc1 <= (10)::numeric)))","CHECK (((diemtc2 >= (0)::numeric) AND (diemtc2 <= (10)::numeric)))","CHECK (((diemtc3 >= (0)::numeric) AND (diemtc3 <= (10)::numeric)))","CHECK ((trangthai = ANY (ARRAY[''DA_DUYET''::text, ''CHO_GOP_Y''::text])))","FOREIGN KEY (mabuoi) REFERENCES vuihoc.\"BUOI_HOC\"(madinhdanh) ON DELETE RESTRICT","FOREIGN KEY (mabuoi) REFERENCES vuihoc.\"CHI_TIET_CA_LOP\"(mabuoi) ON DELETE RESTRICT","FOREIGN KEY (manguoidanhgia) REFERENCES vuihoc.\"NGUOI_DUNG\"(madinhdanh) ON DELETE SET NULL","PRIMARY KEY (madinhdanh)","UNIQUE (mabienban)"]'::jsonb,'[]'::jsonb,'Một biên bản dự giờ; FK buổi xác định ngữ cảnh. Ba điểm là dữ kiện chấm, tổng/xếp loại truy vấn, không chép về giáo viên.'),
 ('BO_LOC_MAU_BAO_CAO','{"mamau":{"type":"text","nullable":"NO","generated":"NEVER"},"truong":{"type":"text","nullable":"NO","generated":"NEVER"},"giatri":{"type":"text","nullable":"NO","generated":"NEVER"},"thutu":{"type":"integer","nullable":"NO","generated":"NEVER"}}'::jsonb,'["CHECK (((btrim(truong) <> ''''::text) AND (btrim(giatri) <> ''''::text) AND (thutu > 0)))","FOREIGN KEY (mamau) REFERENCES vuihoc.\"MAU_BAO_CAO\"(madinhdanh) ON DELETE CASCADE","PRIMARY KEY (mamau, truong, giatri)","UNIQUE (mamau, truong, thutu)"]'::jsonb,'[]'::jsonb,'Một giá trị bộ lọc của mẫu/trường; thứ tự thuộc quan hệ lựa chọn, không chứa tên thuộc tính của thực thể nguồn.'),
 ('BUOI_HOC','{"madinhdanh":{"type":"text","nullable":"NO","generated":"NEVER"},"malop":{"type":"text","nullable":"NO","generated":"NEVER"},"ngayhoc":{"type":"date","nullable":"NO","generated":"NEVER"},"makhunggio":{"type":"text","nullable":"NO","generated":"NEVER"},"magiaovienchinh":{"type":"text","nullable":"NO","generated":"NEVER"},"magiaoviendaythay":{"type":"text","nullable":"YES","generated":"NEVER"},"tieude":{"type":"text","nullable":"NO","generated":"NEVER"},"lienketphonghoc":{"type":"text","nullable":"NO","generated":"NEVER"},"trangthai":{"type":"text","nullable":"NO","generated":"NEVER"},"vaolopluc":{"type":"timestamp with time zone","nullable":"YES","generated":"NEVER"},"ketthucluc":{"type":"timestamp with time zone","nullable":"YES","generated":"NEVER"},"manguoivaolop":{"type":"text","nullable":"YES","generated":"NEVER"},"manguoiketthuc":{"type":"text","nullable":"YES","generated":"NEVER"},"chuyencan":{"type":"text","nullable":"YES","generated":"NEVER"},"nhatky":{"type":"text","nullable":"NO","generated":"NEVER"},"lienketbanghi":{"type":"text","nullable":"YES","generated":"NEVER"},"ngaytao":{"type":"date","nullable":"NO","generated":"NEVER"},"ngaycapnhat":{"type":"date","nullable":"NO","generated":"NEVER"},"hoclieutieude":{"type":"text","nullable":"YES","generated":"NEVER"},"hoclieugiaovien":{"type":"text","nullable":"YES","generated":"NEVER"},"hoclieuhocsinh":{"type":"text","nullable":"YES","generated":"NEVER"},"baitaplms":{"type":"text","nullable":"YES","generated":"NEVER"},"tamhoandolop":{"type":"boolean","nullable":"NO","generated":"NEVER"},"lydotamdung":{"type":"text","nullable":"YES","generated":"NEVER"},"ghichutamdung":{"type":"text","nullable":"YES","generated":"NEVER"},"batdautamdung":{"type":"timestamp with time zone","nullable":"YES","generated":"NEVER"},"manhomtamdung":{"type":"text","nullable":"YES","generated":"NEVER"},"mahoclieu":{"type":"integer","nullable":"YES","generated":"NEVER"}}'::jsonb,'["CHECK (((ketthucluc IS NULL) OR ((vaolopluc IS NOT NULL) AND (ketthucluc >= vaolopluc))))","CHECK (((magiaoviendaythay IS NULL) OR (magiaoviendaythay <> magiaovienchinh)))","CHECK ((chuyencan = ANY (ARRAY[''ATTENDED''::text, ''LATE''::text, ''ABSENT''::text])))","CHECK ((trangthai = ANY (ARRAY[''CHUA_DIEN_RA''::text, ''CHUA_HOC''::text, ''DANG_HOC''::text, ''CHUA_HOAN_TAT''::text, ''DA_HOC''::text, ''NGHI_HOC''::text, ''HUY''::text, ''HOAN_THANH''::text, ''DA_HOC_CU''::text, ''DAY_THAY_CU''::text, ''CO_SU_CO_CU''::text, ''KHAI_GIANG_CU''::text])))","FOREIGN KEY (magiaovienchinh) REFERENCES vuihoc.\"GIAO_VIEN\"(madinhdanh) ON DELETE RESTRICT","FOREIGN KEY (magiaoviendaythay) REFERENCES vuihoc.\"GIAO_VIEN\"(madinhdanh) ON DELETE RESTRICT","FOREIGN KEY (makhunggio) REFERENCES vuihoc.\"KHUNG_GIO\"(madinhdanh) ON DELETE RESTRICT","FOREIGN KEY (malop) REFERENCES vuihoc.\"LOP_HOC\"(madinhdanh) ON DELETE RESTRICT","FOREIGN KEY (malop, mahoclieu) REFERENCES vuihoc.\"HOC_LIEU_LOP\"(malop, mahoclieu) DEFERRABLE INITIALLY DEFERRED","FOREIGN KEY (manguoiketthuc) REFERENCES vuihoc.\"NGUOI_DUNG\"(madinhdanh) ON DELETE SET NULL","FOREIGN KEY (manguoivaolop) REFERENCES vuihoc.\"NGUOI_DUNG\"(madinhdanh) ON DELETE SET NULL","FOREIGN KEY (manhomtamdung, lydotamdung) REFERENCES vuihoc.\"LOAI_SU_CO\"(manhom, madinhdanh) DEFERRABLE INITIALLY DEFERRED","PRIMARY KEY (madinhdanh)","UNIQUE (madinhdanh, malop)","UNIQUE (malop, ngayhoc, makhunggio)"]'::jsonb,'[]'::jsonb,'Một lần học theo ngày; FK lớp/khung giờ/kế hoạch. Giáo viên, thao tác thực tế và ghi đè học liệu có phạm vi riêng; giờ ca JOIN nguồn.'),
 ('CAP_HOC','{"danghoatdong":{"type":"boolean","nullable":"YES","generated":"NEVER"},"madinhdanh":{"type":"text","nullable":"NO","generated":"NEVER"},"tencaphoc":{"type":"text","nullable":"NO","generated":"NEVER"},"nhanhienthi":{"type":"text","nullable":"YES","generated":"NEVER"},"ngaytao":{"type":"date","nullable":"NO","generated":"NEVER"},"ngaycapnhat":{"type":"date","nullable":"NO","generated":"NEVER"}}'::jsonb,'["PRIMARY KEY (madinhdanh)"]'::jsonb,'[]'::jsonb,'Danh mục cấp học; tên đầy đủ và nhãn hiển thị là hai vai trò cấu hình, không giả định chúng phải bằng nhau.'),
 ('CAU_HINH_HE_THONG','{"madinhdanh":{"type":"text","nullable":"NO","generated":"NEVER"},"mavanphongdangchon":{"type":"text","nullable":"YES","generated":"NEVER"},"ngaytao":{"type":"date","nullable":"NO","generated":"NEVER"},"ngaycapnhat":{"type":"date","nullable":"NO","generated":"NEVER"}}'::jsonb,'["FOREIGN KEY (mavanphongdangchon) REFERENCES vuihoc.\"VAN_PHONG_NHAN_XET\"(madinhdanh) ON DELETE SET NULL","PRIMARY KEY (madinhdanh)"]'::jsonb,'["CREATE UNIQUE INDEX cau_hinh_he_thong_mot_ban ON vuihoc.\"CAU_HINH_HE_THONG\" USING btree ((true))"]'::jsonb,'Cấu hình dùng chung; chỉ FK văn phong đang chọn. Một hàng cấu hình, không chép nội dung văn phong.'),
 ('CAU_HINH_TRO_LY','{"madinhdanh":{"type":"text","nullable":"NO","generated":"NEVER"},"loichaomung":{"type":"text","nullable":"NO","generated":"NEVER"},"vanphong":{"type":"text","nullable":"NO","generated":"NEVER"},"chiduatrentailieu":{"type":"boolean","nullable":"NO","generated":"NEVER"},"cautraloiduphong":{"type":"text","nullable":"NO","generated":"NEVER"},"chidanhethong":{"type":"text","nullable":"NO","generated":"NEVER"},"ngaytao":{"type":"date","nullable":"NO","generated":"NEVER"},"ngaycapnhat":{"type":"date","nullable":"NO","generated":"NEVER"}}'::jsonb,'["PRIMARY KEY (madinhdanh)"]'::jsonb,'["CREATE UNIQUE INDEX cau_hinh_tro_ly_mot_ban ON vuihoc.\"CAU_HINH_TRO_LY\" USING btree ((true))"]'::jsonb,'Cấu hình trợ lý; chào hỏi, persona, chỉ dẫn và câu trả lời dự phòng là các vai trò riêng, không phải bản sao văn phong nhận xét.'),
 ('CAU_HOI_CHAT_AI','{"macauhoi":{"type":"uuid","nullable":"NO","generated":"NEVER"},"maphien":{"type":"uuid","nullable":"NO","generated":"NEVER"},"noidung":{"type":"text","nullable":"NO","generated":"NEVER"},"thoigianhoi":{"type":"timestamp with time zone","nullable":"NO","generated":"NEVER"}}'::jsonb,'["CHECK (((length(btrim(noidung)) >= 1) AND (length(btrim(noidung)) <= 120000)))","FOREIGN KEY (maphien) REFERENCES vuihoc.\"PHIEN_CHAT_AI\"(maphien) ON DELETE CASCADE","PRIMARY KEY (macauhoi)"]'::jsonb,'[]'::jsonb,'Một câu hỏi thuộc phiên chat; không chép tài khoản/giáo viên từ đầu phiên, không lưu câu trả lời AI.'),
 ('CHI_SO_MAU_BAO_CAO','{"mamau":{"type":"text","nullable":"NO","generated":"NEVER"},"machiso":{"type":"text","nullable":"NO","generated":"NEVER"},"thutu":{"type":"integer","nullable":"NO","generated":"NEVER"}}'::jsonb,'["CHECK (((btrim(machiso) <> ''''::text) AND (thutu > 0)))","FOREIGN KEY (mamau) REFERENCES vuihoc.\"MAU_BAO_CAO\"(madinhdanh) ON DELETE CASCADE","PRIMARY KEY (mamau, machiso)","UNIQUE (mamau, thutu)"]'::jsonb,'[]'::jsonb,'Chỉ số được chọn của một mẫu; vị trí thuộc lựa chọn. Không lưu kết quả chỉ số.'),
 ('CHI_TIET_CA_LOP','{"khoaca":{"type":"text","nullable":"NO","generated":"NEVER"},"mabuoi":{"type":"text","nullable":"NO","generated":"NEVER"},"sobuoi":{"type":"integer","nullable":"NO","generated":"NEVER"}}'::jsonb,'["CHECK ((sobuoi > 0))","FOREIGN KEY (mabuoi) REFERENCES vuihoc.\"BUOI_HOC\"(madinhdanh)","PRIMARY KEY (mabuoi)"]'::jsonb,'[]'::jsonb,'Một ánh xạ giao diện của buổi; khóa buổi là nguồn, khoaca là khóa hiển thị và sobuoi là thứ tự phiên, không chép lớp/giáo viên/học liệu.'),
 ('CHI_TIET_PHIEN_BAN_LICH_RANH','{"makhunggio":{"type":"text","nullable":"NO","generated":"NEVER"},"thutrongtuan":{"type":"integer","nullable":"NO","generated":"NEVER"},"trangthai":{"type":"text","nullable":"NO","generated":"NEVER"},"maphienban":{"type":"text","nullable":"NO","generated":"NEVER"}}'::jsonb,'["CHECK (((thutrongtuan >= 0) AND (thutrongtuan <= 6)))","CHECK ((trangthai = ANY (ARRAY[''free''::text, ''busy''::text, ''none''::text])))","FOREIGN KEY (makhunggio) REFERENCES vuihoc.\"KHUNG_GIO\"(madinhdanh)","FOREIGN KEY (maphienban) REFERENCES vuihoc.\"PHIEN_BAN_LICH_RANH\"(madinhdanh) ON DELETE CASCADE","PRIMARY KEY (maphienban, makhunggio, thutrongtuan)"]'::jsonb,'[]'::jsonb,'Trạng thái theo phiên bản/khung giờ/thứ. Không chép giáo viên hoặc thời điểm từ đầu phiên bản.'),
 ('CONG_DAY_BUOI_HOC','{"madinhdanh":{"type":"text","nullable":"NO","generated":"NEVER"},"mabuoi":{"type":"text","nullable":"NO","generated":"NEVER"},"magiaovien":{"type":"text","nullable":"NO","generated":"NEVER"},"hesocong":{"type":"numeric","nullable":"NO","generated":"NEVER"},"ghichu":{"type":"text","nullable":"NO","generated":"NEVER"},"dagui":{"type":"boolean","nullable":"NO","generated":"NEVER"},"guiluc":{"type":"date","nullable":"YES","generated":"NEVER"},"ngaytao":{"type":"date","nullable":"NO","generated":"NEVER"},"ngaycapnhat":{"type":"date","nullable":"NO","generated":"NEVER"},"loaicong":{"type":"text","nullable":"NO","generated":"NEVER"},"trangthaidoisoat":{"type":"text","nullable":"NO","generated":"NEVER"}}'::jsonb,'["CHECK (((hesocong >= ''-999.999''::numeric) AND (hesocong <= 999.999)))","CHECK ((loaicong = ANY (ARRAY[''STANDARD''::text, ''COVER''::text, ''STUDENT_CANCELED''::text, ''LATE''::text, ''EMERGENCY''::text, ''APPROVED_EXPLANATION''::text])))","CHECK ((trangthaidoisoat = ANY (ARRAY[''CHO_DOI_SOAT''::text, ''DA_XAC_NHAN''::text, ''CO_GIAI_TRINH''::text, ''DA_CHOT''::text])))","FOREIGN KEY (mabuoi) REFERENCES vuihoc.\"BUOI_HOC\"(madinhdanh) ON DELETE RESTRICT","FOREIGN KEY (magiaovien) REFERENCES vuihoc.\"GIAO_VIEN\"(madinhdanh) ON DELETE RESTRICT","PRIMARY KEY (madinhdanh)","UNIQUE (mabuoi, magiaovien)"]'::jsonb,'[]'::jsonb,'Công thực tế của buổi và người nhận; hệ số/đối soát có vòng đời riêng. Kỳ và vai trò được truy vấn từ buổi.'),
 ('DANG_KY_MON_HOC','{"mahocsinh":{"type":"text","nullable":"NO","generated":"NEVER"},"mamonhoc":{"type":"text","nullable":"NO","generated":"NEVER"},"matrinhdo":{"type":"text","nullable":"NO","generated":"NEVER"},"mamohinh":{"type":"text","nullable":"NO","generated":"NEVER"},"trangthai":{"type":"text","nullable":"NO","generated":"NEVER"},"ngaydangky":{"type":"timestamp with time zone","nullable":"NO","generated":"NEVER"},"dotdangky":{"type":"integer","nullable":"NO","generated":"NEVER"},"loaidangky":{"type":"text","nullable":"NO","generated":"NEVER"},"khoidangky":{"type":"text","nullable":"YES","generated":"NEVER"},"thoihocluc":{"type":"timestamp with time zone","nullable":"YES","generated":"NEVER"},"macaphocdangky":{"type":"text","nullable":"YES","generated":"NEVER"}}'::jsonb,'["CHECK ((dotdangky > 0))","CHECK ((trangthai = ANY (ARRAY[''CHO_XEP_LOP''::text, ''DANG_HOC''::text, ''BAO_LUU''::text, ''DA_THOI_HOC''::text])))","FOREIGN KEY (macaphocdangky, khoidangky) REFERENCES vuihoc.\"LUA_CHON_CAP_HOC\"(macaphoc, madinhdanh) MATCH FULL","FOREIGN KEY (mahocsinh) REFERENCES vuihoc.\"HOC_SINH\"(madinhdanh) ON DELETE CASCADE","FOREIGN KEY (mamohinh) REFERENCES vuihoc.\"MO_HINH_LOP\"(mamohinh) ON UPDATE CASCADE","FOREIGN KEY (mamonhoc) REFERENCES vuihoc.\"MON_HOC\"(mamonhoc) ON UPDATE CASCADE","FOREIGN KEY (matrinhdo) REFERENCES vuihoc.\"TRINH_DO\"(matrinhdo) ON UPDATE CASCADE","PRIMARY KEY (mahocsinh, mamonhoc)"]'::jsonb,'[]'::jsonb,'Yêu cầu môn hiện tại của học sinh; trình độ/mô hình đăng ký khác dữ kiện lớp được xếp. Đợt/khối nhập học là dữ kiện đăng ký.'),
 ('DANH_MUC_BO_SUNG','{"madinhdanh":{"type":"text","nullable":"NO","generated":"NEVER"},"madanhmuc":{"type":"text","nullable":"NO","generated":"NEVER"},"tendanhmuc":{"type":"text","nullable":"NO","generated":"NEVER"},"mota":{"type":"text","nullable":"NO","generated":"NEVER"},"madanhmuccha":{"type":"text","nullable":"YES","generated":"NEVER"},"ngaytao":{"type":"date","nullable":"NO","generated":"NEVER"},"ngaycapnhat":{"type":"date","nullable":"NO","generated":"NEVER"}}'::jsonb,'["CHECK (((btrim(madinhdanh) <> ''''::text) AND (btrim(madanhmuc) <> ''''::text) AND (btrim(tendanhmuc) <> ''''::text)))","FOREIGN KEY (madanhmuccha) REFERENCES vuihoc.\"DANH_MUC_BO_SUNG\"(madinhdanh) ON DELETE RESTRICT","PRIMARY KEY (madinhdanh)","UNIQUE (madanhmuc)"]'::jsonb,'["CREATE UNIQUE INDEX danh_muc_bo_sung_ma_khong_trung ON vuihoc.\"DANH_MUC_BO_SUNG\" USING btree (upper(btrim(madanhmuc)))"]'::jsonb,'Một nhóm danh mục có mã duy nhất; FK cha mô tả phân cấp. Không chép mục con.'),
 ('DANH_MUC_SU_CO','{"madinhdanh":{"type":"text","nullable":"NO","generated":"NEVER"},"manhomsuco":{"type":"text","nullable":"NO","generated":"NEVER"},"tennhomsuco":{"type":"text","nullable":"NO","generated":"NEVER"},"mota":{"type":"text","nullable":"YES","generated":"NEVER"},"ngaytao":{"type":"date","nullable":"NO","generated":"NEVER"},"ngaycapnhat":{"type":"date","nullable":"NO","generated":"NEVER"}}'::jsonb,'["PRIMARY KEY (madinhdanh)"]'::jsonb,'[]'::jsonb,'Một nhóm sự cố; tên nhóm khác tên loại. Mã và định danh là khóa/định danh, không phải hai trường mô tả nhập trùng.'),
 ('DIEM_DANH_BUOI_HOC','{"mabuoi":{"type":"text","nullable":"NO","generated":"NEVER"},"mahocsinh":{"type":"text","nullable":"NO","generated":"NEVER"},"trangthai":{"type":"text","nullable":"NO","generated":"NEVER"},"ghichu":{"type":"text","nullable":"NO","generated":"NEVER"},"manguoicapnhat":{"type":"text","nullable":"YES","generated":"NEVER"},"ngaytao":{"type":"date","nullable":"NO","generated":"NEVER"},"ngaycapnhat":{"type":"date","nullable":"NO","generated":"NEVER"}}'::jsonb,'["CHECK ((trangthai = ANY (ARRAY[''present''::text, ''late''::text, ''absent''::text])))","FOREIGN KEY (mabuoi) REFERENCES vuihoc.\"BUOI_HOC\"(madinhdanh) ON DELETE RESTRICT","FOREIGN KEY (mahocsinh) REFERENCES vuihoc.\"HOC_SINH\"(madinhdanh) ON DELETE RESTRICT","FOREIGN KEY (manguoicapnhat) REFERENCES vuihoc.\"NGUOI_DUNG\"(madinhdanh) ON DELETE SET NULL","PRIMARY KEY (mabuoi, mahocsinh)"]'::jsonb,'[]'::jsonb,'Trạng thái của đúng một học sinh trong một buổi; khác chuyên cần giáo viên. Tên học sinh/lớp/giờ đều JOIN.'),
